import { Request, Response } from 'express';
import { User, UserRole } from './models/User'; // Assuming these models exist

export function checkPermission(req: Request, res: Response) {
  const userId = req.user?.id; // Assuming the user object has an id property

  if (!userId) return res.status(401).json({ error: 'Unauthorized' });

  const role = req.user?.role;

  let allowedPermissions = ['read', 'write', 'admin']; // Default permissions for any user

  switch (role) {
    case UserRole.User:
      allowedPermissions = ['read'];
      break;
    case UserRole.Admin:
      allowedPermissions = ['read', 'write', 'admin'];
      break;
    default:
      console.error(`Unknown user role: ${role}`);
      return res.status(500).json({ error: 'Internal Server Error' });
  }

  const permissionNames = Object.keys(allowedPermissions);

  if (!permissionNames.includes(req.method.toLowerCase())) {
    return res.status(403).json({ error: 'Forbidden' });
  }

  return res.json({ success: true, permissions: allowedPermissions });
}

// Example usage in your routes or controllers
const express = require('express');
const router = express.Router();

router.get('/', async (req, res) => {
  try {
    await checkPermission(req, res);
    res.send('User can read data.');
  } catch (error) {
    res.status(error.statusCode || 500).send(error.message);
  }
});

module.exports = router;
```

This script defines a middleware `checkPermission` that checks if the current user has the specified permissions based on their role. It returns JSON responses indicating whether the request is authorized (`200`, `success: true`) or unauthorized (`401`, `error: 'Unauthorized'`). For admin users, it also allows them to perform administrative actions such as writing.

Remember to replace `'./models/User'` with the actual path to your User model, assuming it exists. Also, ensure that the necessary environment variables are set up correctly for your application to run without errors.

